<?php use App\Models\Paciente; ?>
<section class="page-heading"><p class="eyebrow">Programación · CU13</p><h1>Programar cita</h1><p class="lead">Selecciona los datos y revisa la reserva antes de confirmarla. Horas de America/La_Paz.</p></section>
<?php if($errores): ?><div class="notice notice-error" role="alert"><strong>No se ha registrado la cita.</strong><ul><?php foreach($errores as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="panel booking-form" data-booking-options method="post" action="/citas">
    <input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="_formato" value="html">
    <fieldset><legend><span>1</span> Seleccionar paciente</legend>
        <div class="search-form"><label class="sr-only" for="q">Buscar paciente por nombre, apellido o CI</label><input id="q" name="q" type="search" maxlength="100" value="<?= e($seleccion['q']) ?>" placeholder="Nombre, apellido o CI"><button class="button button-quiet" name="accion" value="actualizar" type="submit" formnovalidate>Buscar paciente</button></div>
        <label for="paciente_id">Paciente activo</label><select id="paciente_id" name="paciente_id" required data-booking-refresh><option value="">Selecciona un paciente</option>
        <?php if($paciente!==null&&!in_array((int)$paciente['id'],array_map('intval',array_column($pacientes['filas'],'id')),true)): ?><option value="<?= (int)$paciente['id'] ?>" selected><?= e(Paciente::codigo((int)$paciente['id']) . ' · ' . $paciente['apellidos'] . ', ' . $paciente['nombres']) ?></option><?php endif; ?>
        <?php foreach($pacientes['filas'] as $p): ?><option value="<?= (int)$p['id'] ?>" <?= $seleccion['paciente_id']===(string)$p['id']?'selected':'' ?>><?= e(Paciente::codigo((int)$p['id']) . ' · ' . $p['apellidos'] . ', ' . $p['nombres']) ?></option><?php endforeach; ?></select>
        <?php if($paciente!==null): ?><p class="booking-selected">Seleccionado: <?= e(Paciente::codigo((int)$paciente['id']) . ' · ' . $paciente['nombres'] . ' ' . $paciente['apellidos']) ?></p><?php endif; ?>
        <p class="form-hint">Solo pacientes activos. <?= $pacientes['total'] ?> resultados · página <?= $pacientes['pagina'] ?> de <?= $pacientes['paginas'] ?>, hasta 20 por página.</p>
        <?php if(!$pacientes['filas']): ?><p>No se encontraron pacientes activos para esta búsqueda.</p><?php endif; ?>
        <div class="form-actions"><?php if($pacientes['pagina']>1): ?><button class="button button-quiet" name="pagina_pacientes" value="<?= $pacientes['pagina']-1 ?>" type="submit" formnovalidate>Pacientes anteriores</button><?php endif; ?><?php if($pacientes['pagina']<$pacientes['paginas']): ?><button class="button button-quiet" name="pagina_pacientes" value="<?= $pacientes['pagina']+1 ?>" type="submit" formnovalidate>Más pacientes</button><?php endif; ?></div>
    </fieldset>
    <fieldset><legend><span>2</span> Especialidad y médico</legend><div class="booking-grid">
        <div class="field-group"><label for="especialidad_id">Especialidad activa</label><select id="especialidad_id" name="especialidad_id" required data-booking-refresh><option value="">Selecciona una especialidad</option><?php foreach($especialidades as $opcion): ?><option value="<?= (int)$opcion['id'] ?>" <?= $seleccion['especialidad_id']===(string)$opcion['id']?'selected':'' ?>><?= e($opcion['nombre']) ?></option><?php endforeach; ?></select></div>
        <div class="field-group"><label for="medico_id">Médico activo</label><select id="medico_id" name="medico_id" required data-booking-refresh><option value="">Selecciona un médico</option><?php foreach($medicos as $opcion): ?><option value="<?= (int)$opcion['id'] ?>" <?= $seleccion['medico_id']===(string)$opcion['id']?'selected':'' ?>><?= e($opcion['apellidos'] . ', ' . $opcion['nombres'] . ' · ' . $especialidad['nombre']) ?></option><?php endforeach; ?></select></div>
    </div><?php if($especialidad!==null&&!$medicos): ?><p>No existen médicos activos para esta especialidad.</p><?php endif; ?></fieldset>
    <fieldset><legend><span>3</span> Fecha y turno disponible</legend>
        <label for="fecha">Fecha de atención</label><input id="fecha" name="fecha" type="date" min="<?= e($hoy) ?>" value="<?= e($seleccion['fecha']) ?>" required data-booking-refresh>
        <button class="button button-quiet" name="accion" value="actualizar" type="submit" formnovalidate data-booking-update>Actualizar opciones y turnos</button>
        <?php if($disponibles===null): ?><p class="form-hint">Selecciona especialidad, médico y fecha para consultar los turnos.</p>
        <?php elseif(!$disponibles['turnos']): ?><p class="empty-state"><?= $sinHorarios?'El médico no tiene horarios registrados.':($disponibles['sin_atencion']?'El médico no atiende ese día o sus horarios están inactivos.':'No quedan turnos libres para la fecha consultada; pueden estar ocupados o ya haber transcurrido.') ?></p>
        <?php else: ?><div class="availability-slots booking-slots" role="group" aria-label="Turnos libres de 30 minutos"><?php foreach($disponibles['turnos'] as $turno): $inicioTurno=(new DateTimeImmutable($turno['inicio']))->format('H:i'); ?><label><input type="radio" name="hora_inicio" value="<?= e($inicioTurno) ?>" required <?= $seleccion['hora_inicio']===$inicioTurno?'checked':'' ?>><span><?= e($inicioTurno . '–' . (new DateTimeImmutable($turno['fin']))->format('H:i')) ?></span></label><?php endforeach; ?></div><?php endif; ?>
        <p class="form-hint">Los turnos son informativos. Se comprobarán nuevamente al guardar; no se reservará otro horario automáticamente.</p>
    </fieldset>
    <fieldset><legend><span>4</span> Motivo y revisión</legend><label for="motivo">Motivo breve (opcional)</label><textarea id="motivo" name="motivo" maxlength="500" rows="3"><?= e($seleccion['motivo']) ?></textarea><p class="form-hint">Máximo 500 caracteres. El motivo no aparecerá en la confirmación.</p>
        <div class="form-actions"><button class="button button-secondary" name="accion" value="previsualizar" type="submit" <?= $paciente===null||$medico===null||empty($disponibles['turnos'])?'disabled':'' ?>>Revisar reserva</button><a class="button button-quiet" href="/citas/nueva">Comenzar de nuevo</a></div>
    </fieldset><p class="form-hint" data-booking-loading hidden role="status">Actualizando opciones y disponibilidad…</p>
</form>
